const d = $json;

const supports = (d.supports || []).join(', ');
const resistances = (d.resistances || []).join(', ');
const pivots = (d.pivot_points || []).join(', ');
const alerts = (d.alerts || []).join('<br>');

const html = `
<h2>AIStockAgent Daily Report</h2>
<b>Symbol:</b> ${d.symbol}<br>
<b>Trend Score:</b> ${d.trend_score}<br>
<b>Trend Direction:</b> ${d.trend_direction}<br>
<b>Delivery %:</b> ${d.delivery_pct}<br>
<b>VWAP:</b> ${d.vwap}<br>
<b>Breakout:</b> ${d.breakout}<br><br>

<b>Supports:</b> ${supports}<br>
<b>Resistances:</b> ${resistances}<br>
<b>Pivot Points:</b> ${pivots}<br><br>

<b>AI Summary:</b><br>${d.ai_summary}<br><br>
<b>AI Recommendations:</b><br>${d.ai_recommendations}<br><br>
<b>Sentiment:</b> ${d.sentiment}<br><br>

<b>Alerts:</b><br>${alerts}
`;

return [{ html }];
